// ---- Day / night ---------------------------------------------------------------
export const DAY_LEN = 720;            // turns per full day
/** Pure function of the turn counter. t: 0..1 through the day (0 = midnight).
 *  light: 0..1 ambient brightness. tint: multiply colour for the world. radius: vision radius. */
export function dayInfo(turn) {
  const t = (((turn + DAY_LEN * 0.32) % DAY_LEN) + DAY_LEN) % DAY_LEN / DAY_LEN; // a new life starts mid-morning
  const seg = (a, b) => Math.min(1, Math.max(0, (t - a) / (b - a)));
  let phase, light, tint;
  const NIGHT = [96, 108, 186], DAWN = [255, 196, 178], DAY = [255, 252, 244], DUSK = [255, 170, 132];
  const mixc = (a, b, k) => a.map((v, i) => Math.round(v + (b[i] - v) * k));
  if (t < 0.20) { phase = 'night'; light = 0.42; tint = NIGHT; }
  else if (t < 0.25) { const k = seg(0.20, 0.25); phase = 'dawn'; light = 0.42 + 0.33 * k; tint = mixc(NIGHT, DAWN, k); }
  else if (t < 0.31) { const k = seg(0.25, 0.31); phase = 'dawn'; light = 0.75 + 0.25 * k; tint = mixc(DAWN, DAY, k); }
  else if (t < 0.72) { phase = 'day'; light = 1; tint = DAY; }
  else if (t < 0.78) { const k = seg(0.72, 0.78); phase = 'dusk'; light = 1 - 0.25 * k; tint = mixc(DAY, DUSK, k); }
  else if (t < 0.84) { const k = seg(0.78, 0.84); phase = 'dusk'; light = 0.75 - 0.33 * k; tint = mixc(DUSK, NIGHT, k); }
  else { phase = 'night'; light = 0.42; tint = NIGHT; }
  return { t, phase, light, tint, radius: phase === 'night' ? 7 : VIS_R };
}

